/* eslint-disable @next/next/no-img-element -- a fixed-size SVG needs no optimisation */

type StampMarkProps = {
  /** Season year printed at the foot of the stamp; omit for the bare mark */
  year?: string;
  className?: string;
};

/**
 * The brand mark: a perforated stamp with a red bauble on gold thread. The
 * artwork lives in public/brand/stamp.svg (generated by scripts/brand); the
 * year is set over it in Archivo so it can change each season.
 */
export function StampMark({ year, className = "" }: StampMarkProps) {
  return (
    <span
      aria-hidden
      className={`[container-type:inline-size] relative inline-block aspect-[108/132] ${className}`}
    >
      <img src="/brand/stamp.svg" alt="" className="block h-full w-full" />
      {year && (
        <span className="font-expanded text-gold-soft tabular absolute inset-x-0 bottom-[10%] text-center text-[13cqw] leading-none font-extrabold tracking-[0.06em]">
          {year}
        </span>
      )}
    </span>
  );
}
